import sys
import json

def process_line(line):
    try:
        data = json.loads(line)
        decision, reasons = evaluate(data)
        return {"decision": decision, "reasons": reasons}
    except Exception as e:
        return {"decision": "deny", "reasons": [str(e)]}

def match_host(host, allowed_hosts):
    for pattern in allowed_hosts:
        if pattern == host:
            return True
        if pattern.startswith("*."):
            suffix = pattern[1:]
            if host.endswith(suffix):
                return True
    return False

def evaluate(data):
    req = data.get("request", {})
    plugins = {p["plugin_id"]: p for p in data.get("registry", [])}
    creds = {c["id"]: c for c in data.get("credentials", [])}
    mems = {m["id"]: m for m in data.get("memories", [])}
    srcs = {s["id"]: s for s in data.get("sources", [])}
    apps = {a["id"]: a for a in data.get("approvals", [])}

    plugin_id = req.get("plugin_id")
    if plugin_id not in plugins:
        return "deny", ["plugin not registered"]

    active_plugins = [p for p in data.get("registry", []) if p["plugin_id"] == plugin_id and p.get("status") == "active"]
    if len(active_plugins) != 1:
        return "deny", ["require exactly one active registry entry"]

    plugin = active_plugins[0]
    if plugin.get("catalog_trust") != "signed" or not plugin.get("catalog_signature_valid"):
        return "deny", ["plugin not signed or valid"]
    if req.get("capability") != plugin.get("capability"):
        return "deny", ["capability mismatch"]

    risk = plugin.get("risk")

    cred_id = req.get("credential_id")
    if cred_id not in creds:
        return "deny", ["credential missing"]
    cred = creds[cred_id]
    if cred.get("status") != "active":
        return "deny", ["inactive credential"]
    if plugin_id not in cred.get("plugin_ids", []):
        return "deny", ["credential not bound to plugin"]

    req_scopes = set(plugin.get("required_scopes", []))
    cred_scopes = set(cred.get("scopes", []))
    if not req_scopes.issubset(cred_scopes):
        return "deny", ["missing scopes"]

    destinations = req.get("destinations", [])
    if not destinations:
        return "deny", ["no destinations"]
    target = req.get("target")
    if destinations[0] != target:
        return "deny", ["first dest must be bound target"]

    allowed_hosts = plugin.get("allowed_hosts", [])
    for d in destinations:
        if not match_host(d, allowed_hosts):
            return "deny", ["destination not allowed"]

    memory_ids = req.get("memory_ids", [])
    visited_mems = set()
    roots = set()

    def check_memory(mid):
        if mid in visited_mems:
            return True
        if mid not in mems:
            raise ValueError(f"missing memory {mid}")
        m = mems[mid]
        if m.get("status") != "active":
            raise ValueError(f"inactive memory {mid}")
        visited_mems.add(mid)
        for s_id in m.get("source_ids", []):
            if s_id not in srcs:
                raise ValueError(f"missing source {s_id}")
            if srcs[s_id].get("status") != "active":
                raise ValueError(f"inactive source {s_id}")
            roots.add(s_id)
        for p_id in m.get("parent_memory_ids", []):
            check_memory(p_id)
        return True

    try:
        for mid in memory_ids:
            check_memory(mid)
    except ValueError as e:
        return "deny", [str(e)]

    if risk == "high":
        for sid in roots:
            s = srcs[sid]
            if s.get("trust") != "signed" or not s.get("signature_valid"):
                return "deny", [f"high risk requires signed and valid roots"]

    app_id = req.get("approval_id")
    if risk == "high":
        if not app_id:
            return "deny", ["high risk requires approval"]
        if app_id not in apps:
            return "deny", ["approval missing"]
        app = apps[app_id]
        if app.get("status") != "active" or app.get("type") != "change_ticket":
            return "deny", ["invalid approval status or type"]
        if app.get("plugin_id") != plugin_id:
            return "deny", ["approval plugin mismatch"]
        if app.get("capability") != req.get("capability"):
            return "deny", ["approval capability mismatch"]
        if app.get("target") != target:
            return "deny", ["approval target mismatch"]
        if app.get("args_digest") != req.get("args_digest"):
            return "deny", ["approval digest mismatch"]
    else:
        if app_id is not None:
            if app_id not in apps:
                return "deny", ["optional approval missing"]
            app = apps[app_id]
            if app.get("status") != "active":
                return "deny", ["optional approval inactive"]

    if req.get("forwards_credential"):
        return "deny", ["credential forwarding not allowed"]

    return "allow", ["all checks passed"]

def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        res = process_line(line)
        print(json.dumps(res))

if __name__ == "__main__":
    main()
EOF
